<section class="page-banner"><div class="container"><div class="section-label">PERSONAL DASHBOARD</div><h1>Good to see you, <?= e(explode(' ',$me['full_name'])[0]) ?>.</h1><p>Manage your upcoming experiences and club memberships.</p></div></section>
<section class="section container"><div class="quick-stats"><div class="stat-card"><span>My memberships</span><strong><?= count(array_filter($memberships,fn($m)=>$m['status']==='approved')) ?></strong><small>Approved club memberships</small></div><div class="stat-card"><span>Event registrations</span><strong><?= count(array_filter($registrations,fn($r)=>$r['status']==='registered')) ?></strong><small>Registered events</small></div><div class="stat-card"><span>Participation</span><strong><?= count(array_filter($registrations,fn($r)=>!empty($r['attended_at']))) ?></strong><small>Events attended</small></div></div><div class="columns-2 gap-large"><div><div class="section-heading slim"><h2>My events</h2><a class="inline-arrow" href="<?= e(url('events')) ?>">Find more →</a></div><div class="card panel"><?php if($registrations): ?><?php foreach($registrations as $r): ?><div class="list-record"><div><strong><a href="<?= e(url('event',['id'=>$r['id']])) ?>"><?= e($r['title']) ?></a></strong><div class="small-muted"><?= e(pretty_date($r['starts_at'])) ?> · <?= e($r['venue']) ?></div></div><?= status_pill($r['event_status']==='cancelled'?'cancelled':$r['status']) ?></div><?php endforeach; ?><?php else: ?><p class="small-muted">You have not registered for an event yet.</p><?php endif; ?></div></div>
<div><div class="section-heading slim"><h2>My clubs</h2><a class="inline-arrow" href="<?= e(url('clubs')) ?>">Explore clubs →</a></div><div class="card panel"><?php if($memberships): ?><?php foreach($memberships as $m): ?><div class="list-record"><div><strong><a href="<?= e(url('club',['id'=>$m['id']])) ?>"><?= e($m['name']) ?></a></strong><div class="small-muted"><?= e($m['category']) ?></div></div><?= status_pill($m['status']) ?></div><?php endforeach; ?><?php else: ?><p class="small-muted">Explore clubs and request membership to get involved.</p><?php endif; ?></div><div class="section-heading slim"><h2>Recent notifications</h2><a class="inline-arrow" href="<?= e(url('notifications')) ?>">View all →</a></div><div class="card panel"><?php if($notifications): ?><?php foreach($notifications as $n): ?><div class="stack-item"><strong><?= e($n['title']) ?></strong><p><?= e($n['message']) ?></p><small><?= e(pretty_date($n['created_at'])) ?></small></div><?php endforeach; ?><?php else: ?><p class="small-muted">No notifications yet.</p><?php endif; ?></div></div></div></section>
